	(19443, 'Sayge\'s Fortune #25', 'Prédiction de Sayge n°25', 'Sayges Horoskop Nr. 25', '', '', 'Fortuna de Sayge n.º 25', '', 'Предсказание Воржея #25', '', '', NULL, NULL, 'Euer Schicksal erwartet Euch in den Höhlen des Wehklagens.', NULL, NULL, NULL, NULL, 'В Пещерах Стенаний тебя ждет удача.', NULL, NULL),
	(19444, 'Formula: Enchant Weapon - Strength', 'Formule : Enchantement d\'arme (Force)', 'Formel: Waffe - Stärke', '', '', 'Fórmula: encantar arma: fuerza', '', 'Формула чар для оружия - сила', '', '', NULL, NULL, 'Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass die Stärke um 15 erhöht wird.', NULL, NULL, NULL, NULL, 'Обучает наложению на оружие ближнего боя чар, повышающих силу на 15. Не может применяться к предметам выше 600-го уровня.', NULL, NULL),
	(19445, 'Formula: Enchant Weapon - Agility', 'Formule : Enchantement d\'arme (Agilité)', 'Formel: Waffe - Beweglichkeit', '', '', 'Fórmula: encantar arma: agilidad', '', 'Формула чар для оружия - ловкость I', '', '', NULL, NULL, 'Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass die Beweglichkeit um 15 erhöht wird.', NULL, NULL, NULL, NULL, 'Обучает наложению на оружие ближнего боя чар, повышающих ловкость на 15. Не может применяться к предметам выше 600-го уровня.', NULL, NULL),
	(19446, 'Formula: Enchant Bracer - Mana Regeneration', 'Formule : Enchantement de brassards (Régénération de mana)', 'Formel: Armschiene - Manaregeneration', '', '', 'Fórmula: encantar brazales: regeneración de maná', '', 'Формула чар для наручей - восполнение маны', '', '', NULL, NULL, 'Lehrt Euch, Armschienen dauerhaft zu verzaubern, sodass sie die Willenskraft um 9 erhöhen.', NULL, NULL, NULL, NULL, 'Обучает наложению на наручи чар, повышающих дух на 9. Не может применяться к предметам выше 600-го уровня.', NULL, NULL),
	(19447, 'Formula: Enchant Bracer - Healing Power', 'Formule : Enchantement de brassards (Pouvoir de guérison)', 'Formel: Armschiene - Heilkraft', '', '', 'Fórmula: encantar brazales: poder de sanación', '', 'Формула чар для наручей - целительная сила', '', '', NULL, NULL, 'Lehrt Euch, Armschienen dauerhaft zu verzaubern, sodass die Zaubermacht um 15 erhöht wird.', NULL, NULL, NULL, NULL, 'Обучает наложению на наручи чар, увеличивающих силу заклинаний на 15. Не может применяться к предметам выше 600-го уровня.', NULL, NULL),
	(19448, 'Formula: Enchant Weapon - Mighty Spirit', 'Formule : Enchantement d\'arme (Esprit renforcé)', 'Formel: Waffe - Mächtige Willenskraft', '', '', 'Fórmula: encantar arma: espíritu poderoso', '', 'Формула чар для оружия - дух I', '', '', NULL, NULL, 'Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass die Willenskraft um 20 erhöht wird.', NULL, NULL, NULL, NULL, 'Обучает наложению на оружие ближнего боя чар, повышающих дух на 20. Не может применяться к предметам выше 600-го уровня.', NULL, NULL),
	(19449, 'Formula: Enchant Weapon - Mighty Intellect', 'Formule : Enchantement d\'arme (Intelligence renforcée)', 'Formel: Waffe - Mächtige Intelligenz', '', '', 'Fórmula: encantar arma: intelecto poderoso', '', 'Формула чар для оружия - интеллект I', '', '', NULL, NULL, 'Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass die Intelligenz um 22 erhöht wird.', NULL, NULL, NULL, NULL, 'Обучает наложению на оружие ближнего боя чар, повышающих интеллект на 22. Не может применяться к предметам выше 600-го уровня.', NULL, NULL),
	(19450, 'A Jubling\'s Tiny Home', 'Mini-maison de jubelin', 'Das kleine Zuhause eines Jublings', '', '', 'Una casita de Jubling', '', 'Домик Жаблинга', '', '', NULL, NULL, 'Lehrt Euch, wie man dieses Haustier beschwört.', NULL, NULL, NULL, NULL, 'Учит призывать этого спутника.', NULL, NULL),
