	(33820, 'Weather-Beaten Fishing Hat', 'Chapeau de pêche déformé', 'Wettergegerbter Angelhut', '', '', 'Sombrero para pescar deteriorado por el tiempo', '', 'Видавшая виды рыболовная шапка', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL),
