	(43729, 'Bonescythe Helmet', 'Casque de la faucheuse d\'os', 'Helm der Knochensense', '', '', 'Casco Segahuesos', '', 'Полный шлем костяной косы', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL),
	(43730, 'Bonescythe Legplates', 'Cuissards de la faucheuse d\'os', 'Beinplatten der Knochensense', '', '', 'Quijotes Segahuesos', '', 'Ножные латы костяной косы', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL),
