	(43733, 'Crown of Faith', 'Couronne de foi', 'Reif des Glaubens', '', '', 'Corona de fe', '', 'Корона веры', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL),
