	(44467, 'Enchant Weapon - Mighty Spellpower', 'Enchantement d\'arme (Puissance des sorts renforcée)', 'Waffe - Mächtige Zaubermacht', '', '', 'Encantar arma: poder con hechizos poderoso', '', 'Чары для оружия - сила заклинаний IV', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL),
	(44468, 'Water Soaked Letter', 'Lettre trempée', 'Wassergetränkter Brief', '', '', 'Carta empapada de agua', '', 'Вымокшее письмо', '', '', NULL, NULL, 'Durch das Wasser wird dieser Brief sehr schwer zu lesen sein.', NULL, NULL, NULL, NULL, 'Повреждено водой так, что его почти невозможно прочитать.', NULL, NULL),
	(44469, 'Enchant Boots - Greater Assault', 'Enchantement de bottes (Assaut supérieur)', 'Stiefel - Großer Sturmangriff', '', '', 'Encantar botas: asalto superior', '', 'Чары для обуви - штурм II', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL),
	(44470, 'Enchant Bracer - Superior Spellpower', 'Enchantement de brassards (Puissance des sorts excellente)', 'Armschiene - Überragende Zaubermacht', '', '', 'Encantar brazales: poder con hechizos excelente', '', 'Чары для наручей - сила заклинаний III', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL),
	(44471, 'Formula: Enchant Cloak - Mighty Stamina', 'Formule : Enchantement de cape (Endurance puissante)', 'Formel: Umhang - Mächtige Rüstung', '', '', 'Fórmula: encantar capa: aguante poderoso', '', 'Формула чар для плаща - выносливость I', '', '', NULL, NULL, 'Lehrt Euch, Umhänge dauerhaft zu verzaubern, sodass die Rüstung um 225 erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher.', NULL, NULL, NULL, NULL, 'Обучает наложению на плащ чар, усиливающих выносливость на 25. Не может применяться к предметам выше 600-го уровня.', NULL, NULL),
	(44472, 'Formula: Enchant Cloak - Greater Speed', 'Formule : Enchantement de cape (Vitesse supérieure)', 'Formel: Umhang - Großes Tempo', '', '', 'Fórmula: encantar capa: velocidad superior', '', 'Формула чар для плаща - скорость II', '', '', NULL, NULL, 'Lehrt Euch, Umhänge dauerhaft zu verzaubern, sodass die Tempowertung um 23 erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher.', NULL, NULL, NULL, NULL, 'Обучает наложению на плащ чар, повышающих скорость на 23. Не может применяться к предметам выше 600-го уровня.', NULL, NULL),
	(44473, 'Formula: Enchant Weapon - Scourgebane', 'Formule : Enchantement d\'arme (Plaie du Fléau)', 'Formel: Waffe - Geißelbann', '', '', 'Fórmula: encantar arma: Finiquiplaga', '', 'Формула чар для оружия - проклятие Плети', '', '', NULL, NULL, 'Lehrt Euch, Zweihandwaffen dauerhaft zu verzaubern, sodass die Angriffskraft gegen Untote um 140 erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher.', NULL, NULL, NULL, NULL, 'Обучает наложению на двуручное оружие ближнего боя чар, увеличивающих силу атаки против нежити на 140. Не может применяться к предметам выше 600-го уровня.', NULL, NULL),
	(44474, 'Fordragon\'s Shield', 'Bouclier de Fordragon', 'Fordragons Schild', '', '', 'Escudo de Fordragón', '', 'Щит Фордрагона', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL),
	(44475, 'Reinforced Crate', 'Caisse renforcée', 'Verstärkte Kiste', '', '', 'Caja reforzada', '', 'Усиленный ящик', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL),
	(44476, 'Alumeth\'s Skull', 'Crâne d\'Alumeth', 'Alumeths Schädel', '', '', 'Cráneo de Alumeth', '', 'Череп Алумета', '', '', NULL, NULL, 'Der Zustand des Schädels beginnt, sich zu verschlechtern, als Ihr ihn aus der Kiste entfernt.', NULL, NULL, NULL, NULL, 'Как только вы вынимаете череп из сундука, он начинает трескаться и рассыпаться.', NULL, NULL),
