	(62552, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Vielleicht habt Ihr mit einer anderen Weissagung mehr Glück.', NULL, NULL, NULL, NULL, 'Возможно, с другим предсказанием вам больше повезет.', NULL, NULL),
	(62553, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Haltet Euch von eigenartigem Fleisch fern.', NULL, NULL, NULL, NULL, 'Не пробуйте загадочное мясо.', NULL, NULL),
	(62554, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Ihr hättet diese Spinne wirklich plündern sollen.', NULL, NULL, NULL, NULL, 'Вам все-таки следовало собрать добычу с того паука...', NULL, NULL),
	(62555, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Traut niemals einem ehrlichen Goblin oder einem nüchternen Zwerg.', NULL, NULL, NULL, NULL, 'Никогда не доверяйте честному гоблину или трезвому дворфу.', NULL, NULL),
	(62556, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Man weiß es nie genau, bis man plündert.', NULL, NULL, NULL, NULL, 'Никогда не знаешь, что попадется в добыче.', NULL, NULL),
	(62557, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Es wird Regen geben.', NULL, NULL, NULL, NULL, 'Ваше будущее сокрыто за пеленой сиреневого дождя.', NULL, NULL),
	(62558, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Ihr werdet das Klimpern goldener Münzen hören.', NULL, NULL, NULL, NULL, 'Вы еще услышите звон золотых монет.', NULL, NULL),
	(62559, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Vertraut auf das Licht, aber behaltet Euer Reittier im Auge.', NULL, NULL, NULL, NULL, 'На Свет надейся, а за скакуном следи.', NULL, NULL),
	(62560, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Steht nie im Schatten von Drachen.', NULL, NULL, NULL, NULL, 'Не стоит прятаться в тени драконьих крыльев.', NULL, NULL),
	(62561, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Der Weg zum Schwarzfels ist mit guten Absichten gepflastert.', NULL, NULL, NULL, NULL, 'Благими намерениями выстлана дорога к Черной горе.', NULL, NULL),
	(62562, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Viele Schlachtzugwipes liegen in nächster Zukunft.', NULL, NULL, NULL, NULL, 'Много рейдов поляжет в самом скором вашем будущем.', NULL, NULL),
	(62563, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Epics sind wie Kinder: die der anderen sind nie so wundervoll wie Eure.', NULL, NULL, NULL, NULL, 'Эпические предметы – как дети: твои – всегда самые лучшие.', NULL, NULL),
	(62564, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Erfahrung, Ehrenpunkte und Fraktionsruf liegen in den kommenden Tagen vor Euch.', NULL, NULL, NULL, NULL, 'Опыт, очки доблести и репутация у фракций ждут вас впереди.', NULL, NULL),
	(62565, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Euer größtes Glück sind die Freunde, die Ihr habt. Besonders Tanks.', NULL, NULL, NULL, NULL, 'Не имей сто золотых, а имей сто друзей. И среди них – побольше танков.', NULL, NULL),
	(62566, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Die Zukunft sieht kataklysmisch aus.', NULL, NULL, NULL, NULL, 'В будущем вас подстерегает катаклизм.', NULL, NULL),
	(62567, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Entdeckt die Schönheit des Gewöhnlichen. Und dann verkauft es für Bares an einen Händler.', NULL, NULL, NULL, NULL, 'Ищите красоту в обычных вещах. И продавайте их торговцам.', NULL, NULL),
	(62568, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Wer ein Blind Date verspricht, ist beim Aufreißen gebunden.', NULL, NULL, NULL, NULL, 'Любите свидания вслепую? Отправляйтесь в подзмелье с незнакомой группой.', NULL, NULL),
	(62569, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Der Segen eines Schamanen ist elementar.', NULL, NULL, NULL, NULL, 'Благословение шамана элементально.', NULL, NULL),
	(62570, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Eure Zukunft sieht rosig aus. Außer Ihr lauft Todesschwinge über den Weg.', NULL, NULL, NULL, NULL, 'Ваше будущее будет блестящим, если вы будете держаться вдали от Смертокрыла.', NULL, NULL),
	(62571, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Eure Chancen, in naher Zukunft eine 100 zu würfeln, stehen nicht schlecht.', NULL, NULL, NULL, NULL, 'Ваши шансы выбросить 100 на костях очень велики.', NULL, NULL),
	(62572, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Ihr werdet beim Angeln ein tiefes Gefühl von Entspannung (und Geduld) empfinden.', NULL, NULL, NULL, NULL, 'Вы обретете небывалое терпение и умение расслабляться благодаря профессии рыболова.', NULL, NULL),
	(62573, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Eines Tages werdet Ihr Euch dieses Reittier leisten können.', NULL, NULL, NULL, NULL, 'Когда-нибудь и вы сможете купить того скакуна.', NULL, NULL),
	(62574, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'ZEIT, NACHZUBESTELLEN! Um mehr Weissagungen zu erhalten, schreibt an F.B. Krazzlestix, Bilgewässer Hafen. Mengenrabatte sind zu günstigen Konditionen erhältlich.', NULL, NULL, NULL, NULL, 'ПРИШЛО ВРЕМЯ ЗАКАЗАТЬ ЕЩЕ! Чтобы получить новые предсказания, обратитесь к Ф.Б.Крезопалкусу, Гавань Трюмных Вод. Оптовые скидки (за скромное вознаграждение).', NULL, NULL),
	(62575, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Ihr habt viele verborgene Talente. Mit mehr Erfahrung werdet Ihr noch mehr hinzugewinnen.', NULL, NULL, NULL, NULL, 'У вас много нераскрытых талантов. И с опытом вы приобретете новые.', NULL, NULL),
	(62576, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Wer eine ganz Armee bekämpft, ist ein Märtyrer; Wer gegen fünf auf einmal kämpft, ist die Elite.', NULL, NULL, NULL, NULL, 'Кто выступает против армии – мученик. Кто сражается с пятерыми – элита.', NULL, NULL),
	(62577, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Ein leichtes Herz trägt Euch durch schlechte Schlachtfelder.', NULL, NULL, NULL, NULL, 'С легким сердцем – через проигранные PvP-сражения.', NULL, NULL),
	(62578, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'All Eure Mühen sind die Reparaturkosten wert.', NULL, NULL, NULL, NULL, 'Все ваши усилия стоят денег на починку экипировки.', NULL, NULL),
	(62579, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Vertraut niemals einem Troll. Und auch keinem Schurken. Besonders keinem Trollschurken.', NULL, NULL, NULL, NULL, 'Никогда не верьте троллям. И разбойникам. В особенности троллям-разбойникам.', NULL, NULL),
	(62580, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Ungläubigkeit zerstört die Magie.', NULL, NULL, NULL, NULL, 'Неверие губит все волшебство.', NULL, NULL),
	(62581, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Die Gelegenheit ist günstig, etwas neues zu probieren. Vielleicht einen neuen Beruf.', NULL, NULL, NULL, NULL, 'Пришло время попробовать что-нибудь новое. Например, новую ремесленную профессию.', NULL, NULL),
	(62582, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Jede Pflanze blüht dann auf, wenn die Zeit reif ist. Und dann pflückt Ihr sie!', NULL, NULL, NULL, NULL, 'Каждому растению – свое время. Но как зацветет – хватайте, не зевайте!', NULL, NULL),
	(62583, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Geht und ruht Euch aus. Ihr habt es Euch verdient. Aber vergesst nicht, in einem Gasthaus auszuruhen!', NULL, NULL, NULL, NULL, 'Отдохните. Вы заслужили отдых. Только отдыхайте в таверне!', NULL, NULL),
	(62584, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Wer einen Wipe erwartet, wird nie enttäuscht.', NULL, NULL, NULL, NULL, 'Кто ожидает, что рейд ляжет, никогда не останется разочарованным.', NULL, NULL),
	(62585, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Seht niemals nach oben, wenn fliegende Reittiere über Euch sind.', NULL, NULL, NULL, NULL, 'Не смотрите вверх, когда над вами пролетают ездовые животные.', NULL, NULL),
	(62586, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Ihr werdet eine große Summe Geld erben. Ihr werdet alles im Auktionshaus verpulvern.', NULL, NULL, NULL, NULL, 'Вам достанется в наследство кругленькая сумма. И вы ее просадите в аукционном доме.', NULL, NULL),
	(62587, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Jemand in Eurem näheren Umkreis möchte mit Euch /flirten.', NULL, NULL, NULL, NULL, 'Кое-кто из знакомых ждет от вас /флирта.', NULL, NULL),
	(62588, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Eure Talente werden anerkannt und belohnt. Wenn Eure Talentverteilung gut ist, natürlich.', NULL, NULL, NULL, NULL, 'Ваши таланты непременно оценят по достоинству. Если, конечно, вы правильно распределите очки талантов.', NULL, NULL),
	(62589, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Hilfe! Ich werde in einer Glückskeksfabrik gefangengehalten!', NULL, NULL, NULL, NULL, 'Помогите! Меня насильно держат в пекарне печенек с предсказаниями!', NULL, NULL),
	(62590, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Morgen wird die Sonne scheinen.', NULL, NULL, NULL, NULL, 'Завтра взойдет солнце.', NULL, NULL),
	(62591, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Ihr werdet ein Geschenk von jemandem erhalten, den Ihr verabscheut.', NULL, NULL, NULL, NULL, 'Вы получите подарок от того, кого терпеть не можете.', NULL, NULL),
	(62592, 'Charred Highland Birch', 'Bouleau des hautes-terres carbonisé', 'Verkohle Hochlandbirke', '', '', 'Abedul de las Tierras Altas carbonizado', '', 'Обуглившаяся высокогорная береза', '', '', NULL, NULL, 'Dieses verbrannte Holz verströmt einen unverwechselbaren Geruch. Kein Wunder, dass die Greifen so leicht darauf reagieren.', NULL, NULL, NULL, NULL, 'От горелого полена исходит запах, который ни с чем не спутать. Неудивительно, что грифоны так живо на него реагируют.', NULL, NULL),
	(62593, 'Invigorated Silt', 'Vase vivifiée', 'Kräftiger Schlick', '', '', 'Cieno vigorizado', '', 'Укрепляющий ил', '', '', NULL, NULL, 'Die Probe hört nicht auf, sich zu verschieben und zu bewegen.', NULL, NULL, NULL, NULL, 'Образец по-прежнему движется и колышется.', NULL, NULL),
	(62594, 'Broken Chalice', 'Calice cassé', 'Zerbrochener Kelch', '', '', 'Cáliz roto', '', 'Разбитая чаша', '', '', NULL, NULL, 'Anscheinend sind hier Edelsteine aus Ihren Fassungen gebrochen worden.', NULL, NULL, NULL, NULL, 'Драгоценные камни, похоже, кто-то выковырял из оправ.', NULL, NULL),
	(62595, 'Dusty Vase', 'Vase poussiéreux', 'Staubige Vase', '', '', 'Jarrón polvoriento', '', 'Пыльная ваза', '', '', NULL, NULL, 'Zerbrochen, zersplittert und alt.', NULL, NULL, NULL, NULL, 'Потрескавшаяся, щербатая, старая.', NULL, NULL),
	(62596, 'Earthen Hieroglyph', 'Hiéroglyphe terrestre', 'Irdene Hieroglyphe', '', '', 'Jeroglífico terráneo', '', 'Иероглиф земли', '', '', NULL, NULL, 'Ein uraltes Wort in einer vergessenen Sprache, in den Stein gekerbt.', NULL, NULL, NULL, NULL, 'Древнее слово на забытом языке, выщербленное в камне.', NULL, NULL),
	(62597, 'Trogg Tool', 'Outil trogg', 'Troggwerkzeug', '', '', 'Herramienta trogg', '', 'Орудие троггов', '', '', NULL, NULL, 'Ein Stein.', NULL, NULL, NULL, NULL, 'Это обыкновенный камень.', NULL, NULL),
	(62598, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Der Beginn aller Weisheit ist das Verlangen nach ihr. Der Weisheit letzter Schluss ist Theorycrafting.', NULL, NULL, NULL, NULL, 'Начало мудрости – желание обрести ее. Конец мудрости – увязание в теоретизировании.', NULL, NULL),
	(62599, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Ihr werdet ein langes, glückliches Leben mit vielen Wiederbelebungen darin haben.', NULL, NULL, NULL, NULL, 'Вы проживете долгую счастливую жизнь, по ходу которой вас не раз воскресят.', NULL, NULL),
	(62600, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Der Weg des Facerollers ist nicht der Weg des Weisen.', NULL, NULL, NULL, NULL, 'Путь однокнопочника – не есть путь мудрости.', NULL, NULL),
	(62601, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Es ist nicht alles Gold, was glänzt. Aber meistens könnt Ihr es für Gold verkaufen.', NULL, NULL, NULL, NULL, 'Не все то золото, что блестит. Но за пару золотых это наверняка можно будет продать.', NULL, NULL),
	(62602, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Ihr teilt gern Eure Weisheit. Wenn Ihr so weitermacht, bleibt Euch nicht viel.', NULL, NULL, NULL, NULL, 'Вы отдадите кому-то частичку своего разума, которая все равно простаивает без толку.', NULL, NULL),
	(62603, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Wenn das Leben Euch Zitronen gibt, bezahlt die Reparaturkosten.', NULL, NULL, NULL, NULL, 'Если жизнь подсовывает вам лимон, готовьтесь раскошелиться на ремонт экипировки.', NULL, NULL),
	(62604, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Die Feder in der Hand ist besser als der Windreiter auf dem Dach.', NULL, NULL, NULL, NULL, 'Синицу в руках можно ощипать на перья для левитации.', NULL, NULL),
	(62605, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Eure Glückszahlen sind: 4 8 15 16 23 42', NULL, NULL, NULL, NULL, 'Выигрышные номера на этой неделе: 4 8 15 16 23 42.', NULL, NULL),
	(62606, 'Fortune Card', 'Carte de bonne aventure', 'Glückskarte', '', '', 'Carta de la fortuna', '', 'Карта удачи', '', '', NULL, NULL, 'Ihr habt viele Freunde und sehr wenige Feinde, die am Leben sind.', NULL, NULL, NULL, NULL, 'У вас много друзей и очень мало врагов среди живых.', NULL, NULL),
	(62607, 'Titan Activation Device', 'Mécanisme d\'activation des titans', 'Aktivierungsgerät der Titanen', '', '', 'Dispositivo de activación titánico', '', 'Активирующее устройство титанов', '', '', NULL, NULL, 'Das Ganze ist größer als die Summe seiner Teile.', NULL, NULL, NULL, NULL, 'Целое всегда больше, чем сумма его составляющих.', NULL, NULL),
